{
  "name": "N8N Mentor AI - Unified Analysis",
  "description": "A unified platform for n8n workflow mentorship and screen analysis. Upload screenshots and chat with an AI mentor to build and debug your automations."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface MessagePart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
}

export enum MessageRole {
  USER = 'user',
  MODEL = 'model'
}

export interface ChatMessage {
  id: string;
  role: MessageRole;
  parts: MessagePart[];
  timestamp: number;
}

export interface AppState {
  messages: ChatMessage[];
  isTyping: boolean;
  selectedImage: string | null;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ChatMessage, MessageRole } from "../types";

const SYSTEM_INSTRUCTION = `Sen uzman bir n8n mentörüsün. Kullanıcıların n8n akışlarını (workflow) geliştirmelerine, hataları ayıklamalarına ve otomasyon süreçlerini öğrenmelerine yardımcı oluyorsun.
Kullanıcı bir ekran görüntüsü paylaştığında:
1. Görüntüdeki n8n nodelarını ve akışı analiz et.
2. Mevcut durumu açıkla.
3. Bir sonraki adımda ne yapması gerektiğini veya mevcut hatanın nasıl çözüleceğini teknik detaylarıyla belirt.
4. Yanıtlarını Türkçe ve profesyonel bir üslupla ver.
Eğer görüntü yoksa, sadece n8n ile ilgili soruları yanıtla. İlgisiz konularda nazikçe konuyu n8n'e geri getir.`;

export const getGeminiResponse = async (
  messages: ChatMessage[],
  currentText: string,
  currentImageBase64?: string | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Format history for the API
  // We take the last few messages to provide context
  const history = messages.map(msg => ({
    role: msg.role === MessageRole.USER ? 'user' : 'model',
    parts: msg.parts.map(p => {
      if (p.text) return { text: p.text };
      if (p.inlineData) return { inlineData: p.inlineData };
      return { text: '' };
    })
  }));

  // Construct current prompt
  const parts: any[] = [];
  if (currentImageBase64) {
    parts.push({
      inlineData: {
        mimeType: "image/png",
        data: currentImageBase64.split(',')[1] // Remove prefix
      }
    });
  }
  parts.push({ text: currentText || "Bu ekran görüntüsünü analiz et ve bana n8n akışında nasıl ilerleyeceğimi söyle." });

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "Üzgünüm, bir yanıt oluşturamadım.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "API anahtarı veya bağlantı hatası oluştu. Lütfen tekrar deneyin.";
  }
};

import React from 'react';
import { ChatMessage, MessageRole } from '../types';

interface MessageListProps {
  messages: ChatMessage[];
  isTyping: boolean;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isTyping }) => {
  const messagesEndRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  return (
    <div className="flex-1 overflow-y-auto p-6 space-y-6 chat-scroll">
      {messages.length === 0 && (
        <div className="h-full flex flex-col items-center justify-center text-center opacity-40">
          <i className="fas fa-robot text-6xl mb-4 text-slate-300"></i>
          <h2 className="text-xl font-semibold text-slate-600">Merhaba! Ben N8N Mentörün.</h2>
          <p className="max-w-sm mt-2 text-slate-500">
            n8n akışını analiz etmem için bir ekran görüntüsü yükleyebilir veya sadece sorularını sorabilirsin.
          </p>
        </div>
      )}

      {messages.map((msg) => (
        <div
          key={msg.id}
          className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'}`}
        >
          <div
            className={`max-w-[80%] rounded-2xl p-4 shadow-sm ${
              msg.role === MessageRole.USER
                ? 'bg-[#ff4d6d] text-white rounded-br-none'
                : 'bg-white text-slate-800 rounded-bl-none border border-slate-100'
            }`}
          >
            {msg.parts.map((part, idx) => (
              <div key={idx} className="space-y-3">
                {part.inlineData && (
                  <img
                    src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`}
                    alt="Workflow Analysis"
                    className="rounded-lg max-w-full h-auto border border-white/20 mb-2"
                  />
                )}
                {part.text && (
                  <p className="whitespace-pre-wrap leading-relaxed">{part.text}</p>
                )}
              </div>
            ))}
            <div className={`text-[10px] mt-2 opacity-60 ${msg.role === MessageRole.USER ? 'text-right' : 'text-left'}`}>
              {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </div>
          </div>
        </div>
      ))}

      {isTyping && (
        <div className="flex justify-start">
          <div className="bg-white border border-slate-100 p-4 rounded-2xl rounded-bl-none shadow-sm flex items-center gap-1">
            <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
            <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
            <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
          </div>
        </div>
      )}
      <div ref={messagesEndRef} />
    </div>
  );
};

export default MessageList;

import React, { useState, useRef, useEffect } from 'react';

interface ChatInputProps {
  onSendMessage: (text: string, imageBase64: string | null) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, disabled }) => {
  const [text, setText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const blob = items[i].getAsFile();
        if (blob) {
          const reader = new FileReader();
          reader.onloadend = () => {
            setSelectedImage(reader.result as string);
          };
          reader.readAsDataURL(blob);
        }
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if ((text.trim() || selectedImage) && !disabled) {
      onSendMessage(text, selectedImage);
      setText('');
      setSelectedImage(null);
    }
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="p-4 bg-white border-t border-slate-100">
      <form onSubmit={handleSubmit} className="max-w-4xl mx-auto space-y-3">
        {selectedImage && (
          <div className="relative inline-block">
            <img src={selectedImage} alt="Preview" className="h-24 w-auto rounded-lg border border-slate-200 shadow-sm" />
            <button
              type="button"
              onClick={() => setSelectedImage(null)}
              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center hover:bg-red-600 transition-colors"
            >
              <i className="fas fa-times text-xs"></i>
            </button>
          </div>
        )}

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={triggerFileUpload}
            className="flex-shrink-0 w-12 h-12 bg-slate-100 text-slate-500 rounded-full flex items-center justify-center hover:bg-slate-200 transition-all border border-slate-200"
            title="Görüntü Yükle"
          >
            <i className="fas fa-image text-xl"></i>
          </button>

          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*"
            className="hidden"
          />

          <div className="flex-1 relative">
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onPaste={handlePaste}
              placeholder="N8N, node'lar veya iş akışları hakkında sor... (Ctrl+V ile resim yapıştır)"
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-full px-6 focus:outline-none focus:ring-2 focus:ring-[#ff4d6d]/20 focus:border-[#ff4d6d] transition-all text-slate-700 placeholder:text-slate-400"
              disabled={disabled}
            />
          </div>

          <button
            type="submit"
            disabled={(!text.trim() && !selectedImage) || disabled}
            className={`flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg ${
              (!text.trim() && !selectedImage) || disabled
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
                : 'bg-[#ff4d6d] text-white hover:bg-[#e63958] active:scale-95 shadow-pink-500/20'
            }`}
          >
            <i className="fas fa-paper-plane"></i>
          </button>
        </div>
        <div className="text-center">
            <span className="text-[10px] text-slate-400 font-medium tracking-wide uppercase">
                Gemini 3 Pro Preview tarafından desteklenmektedir
            </span>
        </div>
      </form>
    </div>
  );
};

export default ChatInput;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';
import { ChatMessage, MessageRole, MessagePart } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  const handleSendMessage = async (text: string, imageBase64: string | null) => {
    const userParts: MessagePart[] = [];

    if (imageBase64) {
      userParts.push({
        inlineData: {
          mimeType: "image/png",
          data: imageBase64.split(',')[1]
        }
      });
    }

    if (text.trim()) {
      userParts.push({ text: text.trim() });
    }

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      parts: userParts,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setIsTyping(true);

    // Call Gemini
    try {
      const responseText = await getGeminiResponse(messages, text, imageBase64);

      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        parts: [{ text: responseText }],
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 overflow-hidden font-sans">
      <Sidebar />

      <main className="flex-1 flex flex-col h-full bg-slate-50 relative">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 z-10 shadow-sm">
          <h2 className="text-lg font-semibold text-slate-800">Birleşik Mentor Paneli</h2>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 px-3 py-1 bg-green-50 text-green-600 rounded-full text-xs font-medium border border-green-100">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              Gemini Bağlandı
            </div>
          </div>
        </header>

        {/* Chat Content Area */}
        <div className="flex-1 flex flex-col min-h-0 bg-[#f8fafc]">
           <MessageList messages={messages} isTyping={isTyping} />
           <ChatInput onSendMessage={handleSendMessage} disabled={isTyping} />
        </div>
      </main>
    </div>
  );
};

export default App;

