import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  const handleSendMessage = async (text: string, imageBase64: string | null) => {
    const userParts: MessagePart[] = [];

    if (imageBase64) {
      userParts.push({
        inlineData: {
          mimeType: "image/png",
          data: imageBase64.split(',')[1]
        }
      });
    }

    if (text.trim()) {
      userParts.push({ text: text.trim() });
    }

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      parts: userParts,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setIsTyping(true);

    // Call Gemini
    try {
      const responseText = await getGeminiResponse(messages, text, imageBase64);

      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        parts: [{ text: responseText }],
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 overflow-hidden font-sans">
      <Sidebar />

      <main className="flex-1 flex flex-col h-full bg-slate-50 relative">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 z-10 shadow-sm">
          <h2 className="text-md font-bold text-[#1e293b]">Ekran Görüntüleri Yükleyip Sorular Sorarak Çok Başarılı İş Akışları Yapabilirsin!</h2>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 px-3 py-1 bg-green-50 text-green-600 rounded-full text-xs font-medium border border-green-100">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              Gemini Bağlandı
            </div>
          </div>
        </header>

        {/* Chat Content Area */}
        <div className="flex-1 flex flex-col min-h-0 bg-[#f8fafc]">
           <MessageList messages={messages} isTyping={isTyping} />
           <ChatInput onSendMessage={handleSendMessage} disabled={isTyping} />
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';

interface ChatInputProps {
  onSendMessage: (text: string, imageBase64: string | null) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, disabled }) => {
  const [text, setText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const blob = items[i].getAsFile();
        if (blob) {
          const reader = new FileReader();
          reader.onloadend = () => {
            setSelectedImage(reader.result as string);
          };
          reader.readAsDataURL(blob);
        }
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if ((text.trim() || selectedImage) && !disabled) {
      onSendMessage(text, selectedImage);
      setText('');
      setSelectedImage(null);
    }
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="p-4 bg-white border-t border-slate-100">
      <form onSubmit={handleSubmit} className="max-w-4xl mx-auto space-y-3">
        {selectedImage && (
          <div className="relative inline-block">
            <img src={selectedImage} alt="Preview" className="h-24 w-auto rounded-lg border border-slate-200 shadow-sm" />
            <button
              type="button"
              onClick={() => setSelectedImage(null)}
              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center hover:bg-red-600 transition-colors"
            >
              <i className="fas fa-times text-xs"></i>
            </button>
          </div>
        )}

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={triggerFileUpload}
            className="flex-shrink-0 w-12 h-12 bg-slate-100 text-slate-500 rounded-full flex items-center justify-center hover:bg-slate-200 transition-all border border-slate-200"
            title="Görüntü Yükle"
          >
            <i className="fas fa-image text-xl"></i>
          </button>

          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*"
            className="hidden"
          />

          <div className="flex-1 relative">
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onPaste={handlePaste}
              placeholder="n8n, node'lar veya iş akışları hakkında sor... (Ctrl+V ile resim yapıştır)"
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-full px-6 focus:outline-none focus:ring-2 focus:ring-[#ff4d6d]/20 focus:border-[#ff4d6d] transition-all text-slate-700 placeholder:text-slate-400"
              disabled={disabled}
            />
          </div>

          <button
            type="submit"
            disabled={(!text.trim() && !selectedImage) || disabled}
            className={`flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg ${
              (!text.trim() && !selectedImage) || disabled
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
                : 'bg-[#ff4d6d] text-white hover:bg-[#e63958] active:scale-95 shadow-pink-500/20'
            }`}
          >
            <i className="fas fa-paper-plane"></i>
          </button>
        </div>
        <div className="text-center">
            <span className="text-[10px] text-slate-400 font-medium tracking-wide uppercase">
                DESIGNED BY SUAT TAYFUN TOPAK
            </span>
        </div>
      </form>
    </div>
  );
};

export default ChatInput;

export interface MessagePart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
}

export enum MessageRole {
  USER = 'user',
  MODEL = 'model'
}

export interface ChatMessage {
  id: string;
  role: MessageRole;
  parts: MessagePart[];
  timestamp: number;
}

export interface Attachment {
  id: string;
  name: string;
  type: string;
  base64: string;
  isImage: boolean;
}

export interface AppState {
  messages: ChatMessage[];
  isTyping: boolean;
  selectedAttachments: Attachment[];
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ChatMessage, MessageRole, Attachment } from "../types";

const SYSTEM_INSTRUCTION = `Sen uzman bir n8n mentörüsün. Kullanıcıların n8n akışlarını (workflow) geliştirmelerine, hataları ayıklamalarına ve otomasyon süreçlerini öğrenmelerine yardımcı oluyorsun.
Kullanıcı bir ekran görüntüsü, JSON iş akışı veya ilgili bir dosya paylaştığında:
1. Paylaşılan materyali (görüntü, JSON veya metin) analiz et.
2. Mevcut durumu açıkla ve n8n perspektifinden değerlendir.
3. Bir sonraki adımda ne yapması gerektiğini veya mevcut hatanın nasıl çözüleceğini teknik detaylarıyla belirt.
4. Yanıtlarını Türkçe ve profesyonel bir üslupla ver.
Eğer dosya veya görüntü yoksa, sadece n8n ile ilgili soruları yanıtla. İlgisiz konularda nazikçe konuyu n8n'e geri getir.`;

export const getGeminiResponse = async (
  messages: ChatMessage[],
  currentText: string,
  attachments: Attachment[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const history = messages.map(msg => ({
    role: msg.role === MessageRole.USER ? 'user' : 'model',
    parts: msg.parts.map(p => {
      if (p.text) return { text: p.text };
      if (p.inlineData) return { inlineData: p.inlineData };
      return { text: '' };
    })
  }));

  const parts: any[] = [];

  // Add all attachments
  for (const attachment of attachments) {
    parts.push({
      inlineData: {
        mimeType: attachment.type,
        data: attachment.base64.split(',')[1]
      }
    });
  }

  // Add the text prompt
  parts.push({ 
    text: currentText || (attachments.length > 0 ? "Bu ekleri analiz et ve bana n8n akışında nasıl ilerleyeceğimi söyle." : "") 
  });

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: parts.filter(p => p.text || p.inlineData) }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "Üzgünüm, bir yanıt oluşturamadım.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "API anahtarı veya bağlantı hatası oluştu. Lütfen tekrar deneyin.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Attachment } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string, attachments: Attachment[]) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, disabled }) => {
  const [text, setText] = useState('');
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const docInputRef = useRef<HTMLInputElement>(null);

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const isImage = file.type.startsWith('image/');
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substring(7),
        name: file.name,
        type: file.type || (file.name.endsWith('.json') ? 'application/json' : 'text/plain'),
        base64: reader.result as string,
        isImage
      };
      setAttachments(prev => [...prev, newAttachment]);
    };
    reader.readAsDataURL(file);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      Array.from(files).forEach(processFile);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1 || items[i].type.indexOf('text') !== -1) {
        const file = items[i].getAsFile();
        if (file) processFile(file);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files) {
      Array.from(files).forEach(processFile);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if ((text.trim() || attachments.length > 0) && !disabled) {
      onSendMessage(text, attachments);
      setText('');
      setAttachments([]);
    }
  };

  const removeAttachment = (id: string) => {
    setAttachments(prev => prev.filter(a => a.id !== id));
  };

  return (
    <div 
      className={`p-4 bg-white border-t border-slate-100 transition-colors ${isDragging ? 'bg-slate-50' : ''}`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {isDragging && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-[#ff4d6d]/5 pointer-events-none border-2 border-dashed border-[#ff4d6d]/20 m-2 rounded-xl">
          <div className="bg-white p-4 rounded-xl shadow-xl flex items-center gap-3">
            <i className="fas fa-cloud-upload-alt text-[#ff4d6d] text-2xl animate-bounce"></i>
            <span className="font-bold text-[#ff4d6d]">Dosyaları Buraya Bırak</span>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="max-w-5xl mx-auto space-y-3">
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-3 pb-2">
            {attachments.map((file) => (
              <div key={file.id} className="relative group">
                {file.isImage ? (
                  <img src={file.base64} alt="Preview" className="h-20 w-20 object-cover rounded-lg border border-slate-200 shadow-sm" />
                ) : (
                  <div className="h-20 w-20 flex flex-col items-center justify-center bg-slate-50 border border-slate-200 rounded-lg p-2 text-center">
                    <i className={`fas ${file.type.includes('json') ? 'fa-file-code text-blue-500' : 'fa-file-alt text-slate-400'} text-xl mb-1`}></i>
                    <span className="text-[8px] font-medium truncate w-full text-slate-600">{file.name}</span>
                  </div>
                )}
                <button
                  type="button"
                  onClick={() => removeAttachment(file.id)}
                  className="absolute -top-2 -right-2 bg-slate-800 text-white rounded-full w-5 h-5 flex items-center justify-center hover:bg-red-500 transition-colors shadow-sm opacity-0 group-hover:opacity-100"
                >
                  <i className="fas fa-times text-[10px]"></i>
                </button>
              </div>
            ))}
          </div>
        )}

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 bg-slate-50 p-1 rounded-full border border-slate-200 shadow-sm">
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="w-10 h-10 text-slate-500 rounded-full flex items-center justify-center hover:bg-white hover:text-[#ff4d6d] hover:shadow-sm transition-all"
              title="Resim Yükle"
            >
              <i className="fas fa-image"></i>
            </button>
            <button
              type="button"
              onClick={() => jsonInputRef.current?.click()}
              className="w-10 h-10 text-slate-500 rounded-full flex items-center justify-center hover:bg-white hover:text-blue-500 hover:shadow-sm transition-all"
              title="n8n JSON Yükle"
            >
              <i className="fas fa-file-code"></i>
            </button>
            <button
              type="button"
              onClick={() => docInputRef.current?.click()}
              className="w-10 h-10 text-slate-500 rounded-full flex items-center justify-center hover:bg-white hover:text-green-500 hover:shadow-sm transition-all"
              title="Dosya Yükle"
            >
              <i className="fas fa-file-lines"></i>
            </button>
          </div>

          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" multiple />
          <input type="file" ref={jsonInputRef} onChange={handleFileChange} accept=".json,application/json" className="hidden" multiple />
          <input type="file" ref={docInputRef} onChange={handleFileChange} className="hidden" multiple />

          <div className="flex-1 relative">
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onPaste={handlePaste}
              placeholder="n8n, node'lar ve/ya iş akışları hakkında sorular sor... (Ekran resmi, json ya da dosya yükle ya da sürükle bırak)"
              className="w-full h-12 bg-white border border-slate-200 rounded-full px-6 focus:outline-none focus:ring-2 focus:ring-[#ff4d6d]/10 focus:border-[#ff4d6d] transition-all text-slate-700 placeholder:text-slate-400 shadow-inner"
              disabled={disabled}
            />
          </div>

          <button
            type="submit"
            disabled={(!text.trim() && attachments.length === 0) || disabled}
            className={`flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg ${
              (!text.trim() && attachments.length === 0) || disabled
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'
                : 'bg-[#ff4d6d] text-white hover:bg-[#e63958] active:scale-95 shadow-pink-500/20'
            }`}
          >
            <i className="fas fa-paper-plane"></i>
          </button>
        </div>
        <div className="text-center">
            <span className="text-[10px] text-slate-400 font-medium tracking-wide uppercase">
                DESIGNED BY SUAT TAYFUN TOPAK
            </span>
        </div>
      </form>
    </div>
  );
};

export default ChatInput;

