import React, { useState, useRef, useEffect } from 'react';
import { Attachment } from '../types';

interface ChatInputProps {
  onSendMessage: (text: string, attachments: Attachment[]) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, disabled }) => {
  const [text, setText] = useState('');
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const isImage = file.type.startsWith('image/');
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substring(7),
        name: file.name,
        type: file.type || (file.name.endsWith('.json') ? 'application/json' : 'text/plain'),
        base64: reader.result as string,
        isImage
      };
      setAttachments(prev => [...prev, newAttachment]);
    };
    reader.readAsDataURL(file);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      Array.from(files).forEach(processFile);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1 || items[i].type.indexOf('text') !== -1) {
        const file = items[i].getAsFile();
        if (file) processFile(file);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files) {
      Array.from(files).forEach(processFile);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if ((text.trim() || attachments.length > 0) && !disabled) {
      onSendMessage(text, attachments);
      setText('');
      setAttachments([]);
    }
  };

  const removeAttachment = (id: string) => {
    setAttachments(prev => prev.filter(a => a.id !== id));
  };

  return (
    <div 
      className={`p-6 bg-white border-t border-slate-100 transition-colors shadow-2xl z-20 ${isDragging ? 'bg-slate-50' : ''}`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {isDragging && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-[#ff4d6d]/5 pointer-events-none border-2 border-dashed border-[#ff4d6d]/20 m-3 rounded-[2rem]">
          <div className="bg-white p-6 rounded-2xl shadow-2xl flex items-center gap-4">
            <i className="fas fa-cloud-upload-alt text-[#ff4d6d] text-4xl animate-bounce"></i>
            <span className="font-black text-xl text-[#ff4d6d]">Dosyaları Buraya Bırakın</span>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="max-w-6xl mx-auto space-y-5">
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-4 pb-4 border-b border-slate-50">
            {attachments.map((file) => (
              <div key={file.id} className="relative group">
                {file.isImage ? (
                  <img src={file.base64} alt="Preview" className="h-28 w-28 object-cover rounded-2xl border-2 border-slate-200 shadow-md group-hover:border-[#ff4d6d] transition-all" />
                ) : (
                  <div className="h-28 w-28 flex flex-col items-center justify-center bg-slate-50 border-2 border-slate-200 rounded-2xl p-3 text-center group-hover:border-[#ff4d6d] transition-all">
                    <i className={`fas ${file.type.includes('json') ? 'fa-file-code text-blue-500' : 'fa-file-alt text-slate-400'} text-3xl mb-2`}></i>
                    <span className="text-[10px] font-black truncate w-full text-slate-600">{file.name}</span>
                  </div>
                )}
                <button
                  type="button"
                  onClick={() => removeAttachment(file.id)}
                  className="absolute -top-3 -right-3 bg-slate-900 text-white rounded-full w-7 h-7 flex items-center justify-center hover:bg-red-500 transition-all shadow-lg opacity-0 group-hover:opacity-100 z-10"
                >
                  <i className="fas fa-times text-sm"></i>
                </button>
              </div>
            ))}
          </div>
        )}

        <div className="flex items-center gap-5">
          <div className="relative group shrink-0">
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="w-14 h-14 bg-[#ff4d6d] text-white rounded-2xl flex items-center justify-center hover:bg-[#e63958] transition-all shadow-xl shadow-pink-500/10 active:scale-90"
            >
              <i className="fas fa-plus text-2xl"></i>
            </button>
            <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-4 px-4 py-2 bg-slate-900 text-white text-xs font-bold rounded-xl opacity-0 group-hover:opacity-100 transition-all whitespace-nowrap pointer-events-none shadow-2xl border border-slate-700 translate-y-2 group-hover:translate-y-0">
              Resim, JSON veya dosya ekle
            </div>
          </div>

          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            className="hidden" 
            multiple 
            accept="image/*,.json,application/json,.txt,.doc,.docx,.pdf,.csv,.xls,.xlsx" 
          />

          <div className="flex-1 relative">
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onPaste={handlePaste}
              placeholder="n8n hakkında ne bilmek istersiniz? (Görsel veya dosya yükleyebilirsiniz)"
              className="w-full h-14 bg-white border-2 border-slate-200 rounded-[1.25rem] px-8 focus:outline-none focus:ring-4 focus:ring-[#ff4d6d]/10 focus:border-[#ff4d6d] transition-all text-lg font-medium text-slate-700 placeholder:text-slate-400 shadow-inner"
              disabled={disabled}
            />
          </div>

          <button
            type="submit"
            disabled={(!text.trim() && attachments.length === 0) || disabled}
            className={`flex-shrink-0 w-14 h-14 rounded-[1.25rem] flex items-center justify-center transition-all shadow-xl ${
              (!text.trim() && attachments.length === 0) || disabled
                ? 'bg-slate-100 text-slate-300 cursor-not-allowed shadow-none'
                : 'bg-[#ff4d6d] text-white hover:bg-[#e63958] active:scale-90 shadow-pink-500/20'
            }`}
          >
            <i className="fas fa-paper-plane text-xl"></i>
          </button>
        </div>

        <div className="flex flex-col md:flex-row items-center justify-center gap-8 md:gap-16 pt-4 border-t border-slate-50">
          <span className="text-[11px] text-slate-400 font-black tracking-[0.2em] uppercase">
              DESIGNED BY SUAT TAYFUN TOPAK
          </span>
          <div className="flex items-center gap-6 text-sm text-slate-600 font-bold">
            <span className="hidden sm:inline">Beğendiysen belki bana bir kahve ısmarlarsın ;)</span>
            <a 
              href="https://buymeacoffee.com/suattayfuntopak" 
              target="_blank" 
              rel="noopener noreferrer"
              className="bg-[#FFDD00] text-black px-6 py-3 rounded-full font-black text-xs hover:scale-105 active:scale-95 transition-all flex items-center gap-3 shadow-xl shadow-yellow-500/20 border border-black/5"
            >
              <img src="https://cdn.buymeacoffee.com/buttons/bmc-new-btn-logo.svg" alt="BMC" className="w-5" />
              Buy me a coffee
            </a>
          </div>
        </div>
      </form>
    </div>
  );
};

