    setMessages(prev => [...prev, userMessage]);
    setIsTyping(true);

    try {
      const responseText = await getGeminiResponse(messages, text, attachments);

      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        parts: [{ text: responseText }],
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error("Chat Error:", error);
    } finally {
      setIsTyping(false);
    }
  };

  const getHeaderTitle = () => {
    switch (activeView) {
      case 'chat': return 'Ekran Görüntüsü, Json ya da Dosya Yükleyip Sorular Sorarak Çok Başarılı İş Akışları Yapabilirsin!';
      case 'links': return 'Faydalı Kaynaklar ve Hızlı Erişim Bağlantıları';
      case 'other-apps': return 'Yapay Zeka Destekli Diğer Çözümlerimiz';
      case 'contact': return 'Suat Tayfun Topak ile İletişime Geçin!';
      default: return 'n8n Mentor AI';
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 overflow-hidden font-sans text-slate-800 antialiased">
      <Sidebar onViewChange={setActiveView} activeView={activeView} />

      <main className="flex-1 flex flex-col h-full bg-slate-50 relative">
        {/* Header */}
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 z-10 shadow-sm shrink-0">
          <h2 className="text-lg font-bold text-[#1e293b] max-w-3xl leading-snug">
            {getHeaderTitle()}
          </h2>
          <div className="flex items-center gap-4 shrink-0">
            <div className="flex items-center gap-3 px-4 py-2 bg-green-50 text-green-600 rounded-full text-sm font-bold border border-green-100">
              <span className="w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse"></span>
              Gemini Aktif
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 flex flex-col min-h-0 bg-[#f8fafc]">
          {activeView === 'chat' && (
            <>
              <MessageList messages={messages} isTyping={isTyping} />
              <ChatInput onSendMessage={handleSendMessage} disabled={isTyping} />
            </>
          )}
          {activeView === 'links' && <LinksDisplay />}
          {activeView === 'other-apps' && <OtherAppsDisplay />}
          {activeView === 'contact' && <ContactDisplay />}
        </div>
      </main>
    </div>
  );
};

